/** OG 카드에 쓰는 로고. 데이터 URI 로 심는 이유:
 *
 *  루트 OG 카드는 빌드 때 미리 그려진다(static + revalidate). 그때는 우리 서버가
 *  안 떠 있어서 `${SITE}/logo.png` 같은 자기 주소로는 satori 가 이미지를 못 받아
 *  그 자리가 빈칸으로 나갔다 (실측). 데이터 URI 는 받아올 것이 없으니 항상 그려진다.
 *
 *  160px 로 줄였다. 카드에서 가장 크게 쓰는 곳이 104px 이라 그 이상은 낭비다.
 *  화면용(헤더)은 next/image 가 public/logo.png 를 알아서 줄인다. */
export const LOGO = "data:image/png;base64,";
